Here is the commit message:
drm/amd: Fix a few more NULL pointer dereference in device
 cleanup

I found a few more paths that cleanup fails due to a NULL version pointer
on unsupported hardware.

Add NULL checks as applicable.

Fixes: 39fc2bc4da00 ("drm/amdgpu: Protect GPU register accesses in powergated state in some paths")
Reviewed-by: Alex Deucher <alexander.deucher@amd.com>
Signed-off-by: Mario Limonciello <mario.limonciello@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>
(cherry picked from commit f5a05f8414fc10f307eb965f303580c7778f8dd2)
Cc: stable@vger.kernel.org

Here is the root cause:
During device cleanup in amdgpu_device_ip_fini_early() and amdgpu_device_ip_fini(), the code dereferences `adev->ip_blocks[i].version->funcs` or `adev->ip_blocks[i].version->type` without checking if `version` is NULL. On unsupported hardware, some IP blocks may have a NULL version pointer, causing a NULL pointer dereference (crash) when trying to access its members during teardown.

Here is the patch:

 static int amdgpu_device_ip_fini_early(struct amdgpu_device *adev)
 {
 	int i, r;

 	for (i = 0; i < adev->num_ip_blocks; i++) {
+		if (!adev->ip_blocks[i].version)
+			continue;
 		if (!adev->ip_blocks[i].version->funcs->early_fini)
 			continue;

 		r = adev->ip_blocks[i].version->funcs->early_fini(&adev->ip_blocks[i]);
 		if (r) {
 			dev_dbg(adev->dev,
 				"early_fini of IP block <%s> failed %d\n",
 				adev->ip_blocks[i].version->funcs->name, r);
 		}
 	}

 	amdgpu_amdkfd_suspend(adev, true);
 	amdgpu_amdkfd_teardown_processes(adev);
 	amdgpu_userq_suspend(adev);

 	/* Workaround for ASICs need to disable SMC first */
 	amdgpu_device_smu_fini_early(adev);

 	for (i = adev->num_ip_blocks - 1; i >= 0; i--) {
 		if (!adev->ip_blocks[i].status.hw)
 			continue;

 		amdgpu_ip_block_hw_fini(&adev->ip_blocks[i]);
 	}

 	if (amdgpu_sriov_vf(adev)) {
 		if (amdgpu_virt_release_full_gpu(adev, false))
 			dev_err(adev->dev,
 				"failed to release exclusive mode on fini\n");
 	}

 	/*
 	 * Driver reload on the APU can fail due to firmware validation because
 	 * the PSP is always running, as it is shared across the whole SoC.
 	 * This same issue does not occur on dGPU because it has a mechanism
 	 * that checks whether the PSP is running. A solution for those issues
 	 * in the APU is to trigger a GPU reset, but this should be done during
 	 * the unload phase to avoid adding boot latency and screen flicker.
 	 */
 	if ((adev->flags & AMD_IS_APU) && !adev->gmc.is_app_apu) {
 		r = amdgpu_asic_reset(adev);
 		if (r)
 			dev_err(adev->dev, "asic reset on %s failed\n", __func__);
 	}

 	return 0;
 }

  */
 static int amdgpu_device_ip_fini(struct amdgpu_device *adev)
 {
 	int i, r;

 	amdgpu_cper_fini(adev);

 	if (amdgpu_sriov_vf(adev) && adev->virt.ras_init_done)
 		amdgpu_virt_release_ras_err_handler_data(adev);

 	if (adev->gmc.xgmi.num_physical_nodes > 1)
 		amdgpu_xgmi_remove_device(adev);

 	amdgpu_amdkfd_device_fini_sw(adev);

 	for (i = adev->num_ip_blocks - 1; i >= 0; i--) {
 		if (!adev->ip_blocks[i].status.sw)
 			continue;

+		if (!adev->ip_blocks[i].version)
+			continue;
 		if (adev->ip_blocks[i].version->type == AMD_IP_BLOCK_TYPE_GMC) {
 			amdgpu_ucode_free_bo(adev);
 			amdgpu_free_static_csa(&adev->virt.csa_obj);
 			amdgpu_device_wb_fini(adev);
 			amdgpu_device_mem_scratch_fini(adev);
 			amdgpu_ib_pool_fini(adev);
 			amdgpu_seq64_fini(adev);
 			amdgpu_doorbell_fini(adev);
 		}
 		if (adev->ip_blocks[i].version->funcs->sw_fini) {
 			r = adev->ip_blocks[i].version->funcs->sw_fini(&adev->ip_blocks[i]);
 			/* XXX handle errors */
 			if (r) {
 				dev_dbg(adev->dev,
 					"sw_fini of IP block <%s> failed %d\n",
 					adev->ip_blocks[i].version->funcs->name,
 					r);
 			}
 		}
 		adev->ip_blocks[i].status.sw = false;
 		adev->ip_blocks[i].status.valid = false;
 	}

 	for (i = adev->num_ip_blocks - 1; i >= 0; i--) {
 		if (!adev->ip_blocks[i].status.late_initialized)
 			continue;
+		if (!adev->ip_blocks[i].version)
+			continue;
 		if (adev->ip_blocks[i].version->funcs->late_fini)
 			adev->ip_blocks[i].version->funcs->late_fini(&adev->ip_blocks[i]);
 		adev->ip_blocks[i].status.late_initialized = false;
 	}

 	amdgpu_ras_fini(adev);
 	amdgpu_uid_fini(adev);

 	return 0;
 }



